"use client";

import Image from "next/image";
import Link from "next/link";

export default function Navbar() {
  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-[#F8F5EF]/90 backdrop-blur-md border-b border-[#E7DED0]">
      <div className="max-w-7xl mx-auto h-20 px-8 flex items-center justify-between">

        {/* Logo */}

        <Link href="/" className="flex items-center gap-3">

          <Image
            src="/images/brand/fio-logo.png"
            alt="Figuring It Out"
            width={42}
            height={42}
          />

          <div>

            <h1 className="font-serif text-xl tracking-wide text-[#1F4633]">
              FIGURING IT OUT™
            </h1>

            <p className="uppercase tracking-[.35em] text-[10px] text-[#7C6A57]">
              Jenn Kassan
            </p>

          </div>

        </Link>

        {/* Navigation */}

        <nav className="hidden lg:flex items-center gap-10 text-sm tracking-wide">

          <Link href="/" className="hover:text-[#B8863B] transition">
            Home
          </Link>

          <Link href="/personal" className="hover:text-[#B8863B] transition">
            Personal
          </Link>

          <Link href="/professional" className="hover:text-[#B8863B] transition">
            Professional
          </Link>

          <Link href="/about" className="hover:text-[#B8863B] transition">
            About
          </Link>

        </nav>

        {/* Button */}

        <Link
          href="/contact"
          className="bg-[#234531] hover:bg-[#1A3527] text-white text-sm font-medium px-6 py-3 rounded-md transition"
        >
          Let's Connect
        </Link>

      </div>
    </header>
  );
}